import java.util.HashMap;
import java.util.Map;

public class SparseSimulator {
  public static void main(String[] args) {
      // En Java, la forma más rústica de simular compresión es usar
      // HashMaps, donde la llave es el índice, y solo guardas lo que NO es cero.
      Map<Integer, Integer> comprimido = new HashMap<>();
      comprimido.put(5, 1);
      comprimido.put(6, 1);
      comprimido.put(8, 2);

      System.out.println(comprimido);
  }
}
